// Tool-result construction, in one place.
import type { CallToolResult } from '@modelcontextprotocol/sdk/types.js'
import type { EngineKind } from '../engine.ts'

/**
 * The per-engine "what the operator does about it" sentence. `npm run verify`
 * inspects index.db — advising it on a catalog-only install points at a tool
 * that errors on the absent db; the catalog's fixable input is the committed
 * artifact + checkout, regenerated by `registry:build`.
 */
export const INDEX_REMEDY: Record<EngineKind, string> = {
  db: 'the server operator can check it by running `npm run verify` against the index.',
  catalog:
    'the catalog artifact ships with the package, so the server operator can get a fresh ' +
    'one by updating it.',
  web:
    'this engine fetches from the deployed registry — check network access to the ' +
    'registry origin (or the --registry-url override) and retry.',
}

/**
 * Tool annotations, per engine and per tool.
 *
 * `readOnlyHint` is unconditional: every tool here reads, none mutates a
 * project, on any engine.
 *
 * `openWorldHint` is the half that is NOT constant, and the shared `false` this
 * replaces was a lie on the default engine. On db and catalog every answer
 * comes from a local store. On WEB, `get_component_source` fetches
 * /r/<name>.json from the deployed registry and carries ENCODE_UI_TOKEN in an
 * Authorization header when the operator set one — a network egress plus a
 * credential, which a host that reads this hint for its approval or sandbox
 * policy was never asked about. That is ONE tool on ONE engine, so the
 * annotation says exactly that rather than blanket-declaring an open world for
 * all eight (the index fetch itself is startup, not a tool call).
 */
export const annotations = (
  kind: EngineKind,
  opts: { network?: boolean } = {},
): { readOnlyHint: true; openWorldHint: boolean } => ({
  readOnlyHint: true,
  openWorldHint: kind === 'web' && opts.network === true,
})

/** A prose-only result. */
export const textOnly = (text: string): CallToolResult => ({
  content: [{ type: 'text', text }],
})

/**
 * Both channels from one object: the structured payload the SDK validates, plus
 * prose for hosts that render the text block.
 *
 * Which one a host shows is its choice — Claude Code renders `structuredContent`
 * and discards the text. That is why the prose here is curated rather than a
 * JSON.stringify of the same object: on a host that does render it, dumped JSON
 * is strictly worse than a sentence, and on one that doesn't, it costs nothing.
 *
 * The generic needs no `as` cast: z.infer yields a mapped type, which TypeScript
 * gives an implicit index signature.
 */
export const ok = <T extends Record<string, unknown>>(
  text: string,
  structured: T,
): CallToolResult => ({
  content: [{ type: 'text', text }],
  structuredContent: structured,
})

/**
 * A failure whose message is written FOR THE MODEL: no paths, no stack, and
 * always a next action it can take on its own.
 *
 * The SDK turns any throw into `{isError: true, content:[{text: err.message}]}`
 * and skips output validation for it, so an error result legitimately carries no
 * structuredContent.
 */
export class ToolError extends Error {
  override readonly name = 'ToolError'
}

/**
 * The operator/model split.
 *
 * Un-wrapped, a SQLite failure hands the model `SQLITE_ERROR: no such column …`
 * and a filesystem failure hands it an absolute path — neither actionable, both
 * leaking internals into the context window. stderr gets the raw stack, where
 * paths are exactly what the operator needs (a corrupt payload's filename lands
 * there); the model gets one sentence with the ENGINE'S OWN remedy.
 *
 * ToolError passes through untouched: those messages were written deliberately.
 */
export async function guarded<T>(
  tool: string,
  kind: EngineKind,
  fn: () => T | Promise<T>,
): Promise<T> {
  try {
    return await fn()
  } catch (err) {
    if (err instanceof ToolError) throw err
    process.stderr.write(`[encode-ui-rag] ${tool} failed: ${(err as Error).stack ?? String(err)}\n`)
    throw new ToolError(
      'The registry index could not answer this request. It may be missing or stale; ' +
        INDEX_REMEDY[kind],
    )
  }
}
